package com.live_jgv.betting.academic;
import org.junit.jupiter.api.*;import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.transaction.*;import org.springframework.transaction.support.*;
import org.springframework.amqp.core.*;import org.springframework.amqp.rabbit.core.RabbitTemplate;import org.springframework.amqp.rabbit.connection.CorrelationData;
import java.util.*;import static org.junit.jupiter.api.Assertions.*;import static org.mockito.Mockito.*;
class AcademicPublicationTest {
 JdbcTemplate jdbc;PlatformTransactionManager manager;RabbitTemplate rabbit;AcademicOutboxDispatcher dispatcher;
 @BeforeEach void setup(){jdbc=mock(JdbcTemplate.class);manager=mock(PlatformTransactionManager.class);rabbit=mock(RabbitTemplate.class);when(manager.getTransaction(any())).thenReturn(new SimpleTransactionStatus());when(jdbc.queryForList(anyString())).thenReturn(List.of(Map.of("command_id","cmd","payload","{}","destination_queue","betting_commands")));when(jdbc.update(anyString(),eq("cmd"))).thenReturn(1);dispatcher=new AcademicOutboxDispatcher(jdbc,new TransactionTemplate(manager),new AcademicRabbitSender(rabbit,"","betting_commands",1),"betting_commands");}
 void confirm(boolean ack){doAnswer(invocation->{Message m=invocation.getArgument(2);assertEquals(MessageDeliveryMode.PERSISTENT,m.getMessageProperties().getDeliveryMode());assertEquals("cmd",m.getMessageProperties().getMessageId());CorrelationData c=invocation.getArgument(3);c.getFuture().complete(new CorrelationData.Confirm(ack,null));return null;}).when(rabbit).send(eq(""),eq("betting_commands"),any(Message.class),any(CorrelationData.class));}
 @Test void confirmedRoutingPrecedesPublicationMarker(){confirm(true);assertTrue(dispatcher.drainOne());var order=inOrder(rabbit,jdbc,manager);order.verify(rabbit).send(eq(""),eq("betting_commands"),any(Message.class),any(CorrelationData.class));order.verify(jdbc).update(contains("SET published_at"),eq("cmd"));order.verify(manager).commit(any());}
 @Test void nackRetainsOutbox(){confirm(false);assertThrows(IllegalStateException.class,()->dispatcher.drainOne());verify(jdbc,never()).update(contains("published_at"),eq("cmd"));verify(manager).rollback(any());}
 @Test void missingConfirmRetainsOutbox(){assertThrows(IllegalStateException.class,()->dispatcher.drainOne());verify(manager).rollback(any());verify(jdbc,never()).update(anyString(),eq("cmd"));}
 @Test void returnedUnroutableMessageIsNotSuccess(){doAnswer(i->{CorrelationData c=i.getArgument(3);c.setReturned(new ReturnedMessage(i.getArgument(2),312,"NO_ROUTE","","betting_commands"));c.getFuture().complete(new CorrelationData.Confirm(true,null));return null;}).when(rabbit).send(anyString(),anyString(),any(Message.class),any(CorrelationData.class));assertThrows(IllegalStateException.class,()->dispatcher.drainOne());verify(manager).rollback(any());}
 @Test void missingMarkerAfterConfirmAllowsStableIdentityRetry(){confirm(true);when(jdbc.update(anyString(),eq("cmd"))).thenReturn(0);assertThrows(IllegalStateException.class,()->dispatcher.drainOne());verify(manager).rollback(any());}
 @Test void changedDestinationRequiresReview(){when(jdbc.queryForList(anyString())).thenReturn(List.of(Map.of("command_id","cmd","payload","{}","destination_queue","different")));assertThrows(IllegalStateException.class,()->dispatcher.drainOne());verify(rabbit,never()).send(anyString(),anyString(),any(Message.class),any(CorrelationData.class));}
 @Test void dispatcherDoesNotOvertakeAnEarlierPendingCommand(){when(jdbc.queryForList(anyString())).thenReturn(List.of());assertFalse(dispatcher.drainOne());verify(jdbc).queryForList(argThat((String s)->s.contains("NOT EXISTS")&&s.contains("earlier.source_version<o.source_version")&&s.contains("FOR UPDATE OF o SKIP LOCKED")));}
}
